1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * The single derived duplicate-detection key for an owner. All duplicate detection on create flows
9	 * through this one value: the full lower-case SHA-256 hex over
10	 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)} — the normalized (E.164)
11	 * telephone, a {@code '|'}, the email (lower-cased and trimmed, or empty when absent), a {@code '|'},
12	 * and the {@link Soundex Soundex} encoding of the last name. Two owners are duplicates only when
13	 * this whole key is equal — so, because the telephone is part of the key, two owners who share a last
14	 * name (and even a postcode) but have different telephones have different keys and are both allowed
15	 * (surfaced instead as a soft match). The household id is no longer part of the key.
16	 */
17	public final class OwnerIdentity {
18	
19	    private OwnerIdentity() {
20	    }
21	
22	    public static String key(Owner owner) {
23	        String canonical = telephone(owner.getTelephone()) + "|" + email(owner.getEmail()) + "|"
24	                + Soundex.of(owner.getLastName());
25	        return ShaHex.lowerHex(canonical);
26	    }
27	
28	    /** Normalized telephone: the E.164 form used everywhere else (see {@link TelephoneNormalizer}). */
29	    private static String telephone(String telephone) {
30	        return telephone == null ? "" : TelephoneNormalizer.comparisonKey(telephone);
31	    }
32	
33	    /** Email lower-cased and trimmed; a null/blank email contributes the empty string. */
34	    private static String email(String email) {
35	        return email == null ? "" : email.strip().toLowerCase(Locale.ROOT);
36	    }
37	}
38

