1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * The owner's member id — the single unified identity every other value hangs off. It is
7	 * {@code '<REGION><FY><HASH8><CHK>'}:
8	 * <ul>
9	 * <li>REGION is the canonical region derived from the owner's postcode (falling back to the city
10	 *     table via {@link Locality});</li>
11	 * <li>FY is the two-digit fiscal year (starting 1 July) of the business-day-adjusted
12	 *     registration date (see {@link FiscalYear});</li>
13	 * <li>HASH8 is the first 8 UPPER-case hex characters of SHA-256 over the normalized (E.164)
14	 *     telephone concatenated with the last name — the same hash used by the region-and-hash
15	 *     identity;</li>
16	 * <li>CHK is a single Luhn check digit ({@link CheckDigit}) computed over the digits of
17	 *     {@code <REGION><FY><HASH8>}.</li>
18	 * </ul>
19	 *
20	 * <p>There are no sequence numbers: the id is a pure function of region, fiscal year, telephone
21	 * and last name, so it needs no repository scan and is stable for a given owner. The create audit
22	 * line and the owner segment are built from this one value.
23	 */
24	public final class MemberId {
25	
26	    private MemberId() {
27	    }
28	
29	    /** The {@code '<REGION><FY><HASH8><CHK>'} member id for {@code owner}. */
30	    public static String of(Owner owner) {
31	        String region = Locality.of(owner.getCity(), owner.getPostcode());
32	        String fy = String.format("%02d", FiscalYear.of(owner.getRegistrationDate()) % 100);
33	        String hash8 = ShaHex.upperPrefix(owner.getTelephone() + owner.getLastName(), 8);
34	        String base = region + fy + hash8;
35	        return base + CheckDigit.of(base);
36	    }
37	
38	    /**
39	     * De-duplicate a computed member id against those already in use. When {@code memberId}
40	     * collides with an existing owner's member id, the smallest {@code n} of 2 or more is
41	     * appended as {@code '-<n>'} to make it unique; a member id that does not collide is returned
42	     * unchanged (as is a {@code null} member id).
43	     *
44	     * @param memberId       the computed member id to make unique
45	     * @param existingIds    the member ids already assigned to other owners
46	     * @return the de-duplicated member id
47	     */
48	    public static String dedupe(String memberId, java.util.Set<String> existingIds) {
49	        if (memberId == null || !existingIds.contains(memberId)) {
50	            return memberId;
51	        }
52	        for (int n = 2; ; n++) {
53	            String candidate = memberId + "-" + n;
54	            if (!existingIds.contains(candidate)) {
55	                return candidate;
56	            }
57	        }
58	    }
59	}
