1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import jakarta.validation.Valid;
7	import net.officefloor.plugin.variable.Out;
8	import org.springframework.samples.petclinic.mapper.OwnerMapper;
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.repository.OwnerRepository;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
13	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
14	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
15	import org.springframework.samples.petclinic.rest.escalation.RegistrationDateInFutureException;
16	import org.springframework.validation.annotation.Validated;
17	import org.springframework.web.bind.annotation.RequestBody;
18	
19	@Validated
20	public class BuildOwner {
21	
22	    /** Simple syntactic email check: non-space local part, '@', non-space domain with a dot. */
23	    private static final java.util.regex.Pattern EMAIL =
24	            java.util.regex.Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
25	
26	    /** Fixed public holidays the business-day roll skips (rolls forward to the next non-holiday business day). */
27	    private static final java.util.Set<java.time.LocalDate> HOLIDAYS = java.util.Set.of(
28	            java.time.LocalDate.parse("2026-01-01"), java.time.LocalDate.parse("2026-01-26"),
29	            java.time.LocalDate.parse("2026-04-25"), java.time.LocalDate.parse("2026-12-25"),
30	            java.time.LocalDate.parse("2026-12-28"));
31	
32	    public void service(@Valid @RequestBody OwnerFieldsDto request, OwnerMapper ownerMapper,
33	            OwnerRepository ownerRepository, Out<Owner> built, Out<Boolean> sharesHousehold)
34	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException,
35	            RegistrationDateInFutureException {
36	        // Normalize the address up front so the required-field check rejects an address that is
37	        // blank once trimmed/collapsed, and every later step (and the stored value) sees the
38	        // canonical form.
39	        String normalizedAddress = canonicalizeAddress(request);
40	        requireFields(request, normalizedAddress);
41	        request.setTelephone(TelephoneNormalizer.normalize(request.getTelephone()));
42	        request.setEmail(normalizeEmail(request.getEmail()));
43	        Owner owner = ownerMapper.toOwner(request);
44	        // The EFFECTIVE registration date (supplied or defaulted to the server date) must fall on
45	        // a business day: a Saturday or Sunday rolls forward to the next Monday. Every value
46	        // derived from the registration date (e.g. the membership number's year segment, the daily
47	        // create-limit's day) then uses this adjusted date.
48	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
49	        java.time.LocalDate serverDate = java.time.LocalDate.now();
50	        if (registrationDate == null) {
51	            registrationDate = serverDate;
52	        } else if (registrationDate.isAfter(serverDate)) {
53	            // A supplied registration date cannot be in the future.
54	            throw new RegistrationDateInFutureException(registrationDate, serverDate);
55	        }
56	        owner.setRegistrationDate(toBusinessDay(registrationDate));
57	        owner.setMemberId(MemberId.of(owner));
58	        built.set(owner);
59	        sharesHousehold.set(Boolean.TRUE.equals(request.getSharesHousehold()));
60	    }
61	
62	    /**
63	     * Canonicalize the address supplied on the request and write the canonical values back so the
64	     * mapped owner and every later step see them. Structured fields are preferred: the normalized
65	     * {@code addressLine1}/{@code addressLine2} are stored (or {@code null} when blank), and the
66	     * flat {@code address} becomes the composed, normalized string — the normalized addressLine1
67	     * with a single space and the normalized addressLine2 appended when present, else the
68	     * normalized flat address. Returns that composed address for the required-field check, so an
69	     * owner supplying an address in EITHER form (a non-blank addressLine1, or the flat address) is
70	     * accepted.
71	     */
72	    private static String canonicalizeAddress(OwnerFieldsDto request) {
73	        String line1 = AddressNormalizer.normalize(request.getAddressLine1());
74	        String line2 = AddressNormalizer.normalize(request.getAddressLine2());
75	        String composed = AddressNormalizer.compose(line1, line2, request.getAddress());
76	        request.setAddressLine1(line1.isEmpty() ? null : line1);
77	        request.setAddressLine2(line2.isEmpty() ? null : line2);
78	        request.setAddress(composed);
79	        return composed;
80	    }
81	
82	    /**
83	     * Enforce the owner's required fields, collecting every missing one so the caller reports them
84	     * together. {@code normalizedAddress} is the already-canonicalized address, so an address blank
85	     * once trimmed/collapsed counts as missing.
86	     */
87	    private static void requireFields(OwnerFieldsDto request, String normalizedAddress)
88	            throws MissingOwnerFieldsException {
89	        List<String> missing = new ArrayList<>();
90	        if (isBlank(request.getFirstName())) {
91	            missing.add("firstName");
92	        }
93	        if (isBlank(request.getLastName())) {
94	            missing.add("lastName");
95	        }
96	        if (normalizedAddress.isEmpty()) {
97	            missing.add("address");
98	        }
99	        if (isBlank(request.getCity())) {
100	            missing.add("city");
101	        }
102	        if (isBlank(request.getTelephone())) {
103	            missing.add("telephone");
104	        }
105	        if (!missing.isEmpty()) {
106	            throw new MissingOwnerFieldsException(missing);
107	        }
108	    }
109	
110	    /**
111	     * Roll a registration date forward to the next business day: a Saturday or Sunday, or a date
112	     * on the fixed public-holiday list, moves forward one day at a time until it lands on a
113	     * non-weekend, non-holiday day; a plain weekday is returned unchanged.
114	     */
115	    private static java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
116	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
117	                || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
118	                || HOLIDAYS.contains(date)) {
119	            date = date.plusDays(1);
120	        }
121	        return date;
122	    }
123	
124	    /** When present, require a syntactically valid address and store it lower-cased; else reject with 400. */
125	    private static String normalizeEmail(String email) throws InvalidEmailException {
126	        if (email == null || email.isBlank()) {
127	            return null;
128	        }
129	        String trimmed = email.trim();
130	        if (!EMAIL.matcher(trimmed).matches()) {
131	            throw new InvalidEmailException(email);
132	        }
133	        return trimmed.toLowerCase(java.util.Locale.ROOT);
134	    }
135	
136	    private static boolean isBlank(String value) {
137	        return value == null || value.isBlank();
138	    }
139	}
