1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Single home for how owners are grouped into a household and how a household's stable shared id is
9	 * derived. Parallels {@link OwnerIdentity} (the duplicate key) and {@link MemberId} (the
10	 * member id): the create pipeline's {@link AssignOwnerHousehold} goes through here, so the
11	 * grouping rule and the id derivation stay defined in one place.
12	 *
13	 * <p>The household is keyed on {@code (normalizedLastName, postcode)}: two owners belong to the
14	 * same household exactly when they share a normalized last name and postcode. The
15	 * {@code householdId} is derived DETERMINISTICALLY from those same two fields (see
16	 * {@link #id(Owner)}), so owners with the same last name and postcode compute the identical value
17	 * automatically — there is no longer a stored value to reuse.
18	 */
19	final class Household {
20	
21	    private Household() {
22	    }
23	
24	    /** Comparison key for a last name: leading/trailing and repeated whitespace collapsed, lower-cased. */
25	    static String lastNameKey(String lastName) {
26	        if (lastName == null) {
27	            return "";
28	        }
29	        return lastName.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
30	    }
31	
32	    /** The postcode contribution to the household key: trimmed, or empty when absent. */
33	    private static String postcodeKey(String postcode) {
34	        return postcode == null ? "" : postcode.strip();
35	    }
36	
37	    /**
38	     * The household's stable shared identifier for {@code owner}, derived deterministically as the
39	     * first 12 hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. Owners
40	     * that share a normalized last name and postcode therefore compute the same value without any
41	     * coordination.
42	     */
43	    static String id(Owner owner) {
44	        return ShaHex.upperPrefix(lastNameKey(owner.getLastName()) + "|" + postcodeKey(owner.getPostcode()), 12);
45	    }
46	}
47

1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Derives an owner's marketing segment, formatted {@code '<TIER>_<AREA>'} — one of
7	 * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
8	 * {@code STANDARD_REGIONAL}.
9	 *
10	 * <p>TIER is {@code PREMIUM} when the owner's {@link #level(Owner) membership level} is 3 or
11	 * more, otherwise {@code STANDARD}. AREA is {@code METRO} when the owner's locality (the region
12	 * embedded in the {@link MemberId member id}, re-derived here from the owner's city and postcode)
13	 * is a known region — NSW, VIC or QLD — otherwise {@code REGIONAL}.
14	 */
15	public final class OwnerSegment {
16	
17	    /** Membership level at or above which an owner is in the PREMIUM tier. */
18	    private static final int PREMIUM_THRESHOLD = 3;
19	
20	    private OwnerSegment() {
21	    }
22	
23	    /** The {@code '<TIER>_<AREA>'} segment for {@code owner}. */
24	    public static String of(Owner owner) {
25	        String tier = level(owner) >= PREMIUM_THRESHOLD ? "PREMIUM" : "STANDARD";
26	        String region = Locality.of(owner.getCity(), owner.getPostcode());
27	        String area = Locality.timezone(region) != null ? "METRO" : "REGIONAL";
28	        return tier + "_" + area;
29	    }
30	
31	    /** The owner's effective membership level: the stored value when present, else the derived one. */
32	    private static int level(Owner owner) {
33	        return owner.getMembershipLevel() != null ? owner.getMembershipLevel() : MembershipLevel.of(owner);
34	    }
35	}
