1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.slf4j.Logger;
7	import org.slf4j.LoggerFactory;
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	import tools.jackson.databind.json.JsonMapper;
11	
12	/**
13	 * Emits the create audit trail. Runs after the owner is saved (so its id is
14	 * assigned) and before the response is sent.
15	 *
16	 * <p>Two things are written to the dedicated {@code AUDIT} logger:
17	 * <ol>
18	 * <li>the human-readable audit line carrying the new owner's id, member id,
19	 *     registration date and derived membership level; and</li>
20	 * <li>an immutable, machine-readable {@code OWNER_CREATED} event as a single JSON
21	 *     object {@code {seq, ownerId, memberId, membershipLevel, event}}.</li>
22	 * </ol>
23	 *
24	 * <p>{@code seq} is a monotonically increasing integer across creates. The event
25	 * carries the owner's primary identifier — the unified {@link MemberId member id}.
26	 */
27	public class AuditOwnerCreated {
28	
29	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
30	
31	    /** Monotonically increasing sequence across all creates (process-wide). */
32	    private static final AtomicLong SEQ = new AtomicLong();
33	
34	    private static final JsonMapper MAPPER = JsonMapper.builder().build();
35	
36	    public void service(@Val Owner owner) {
37	        AUDIT.info("Owner created id={} memberId={} registrationDate={} membershipLevel={}",
38	                owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
39	                MembershipLevel.of(owner));
40	
41	        OwnerCreatedEvent event = new OwnerCreatedEvent(SEQ.incrementAndGet(), owner.getId(),
42	                owner.getMemberId(), membershipLevel(owner));
43	        AUDIT.info(MAPPER.writeValueAsString(event));
44	    }
45	
46	    /** Stored membership level if the pipeline has stamped one, else the derived level. */
47	    private static int membershipLevel(Owner owner) {
48	        return owner.getMembershipLevel() != null ? owner.getMembershipLevel() : MembershipLevel.of(owner);
49	    }
50	
51	    /**
52	     * Immutable structured create event. Field order is the serialized JSON key order:
53	     * {@code {seq, ownerId, memberId, membershipLevel, event}}.
54	     */
55	    public record OwnerCreatedEvent(long seq, Integer ownerId, String memberId, int membershipLevel,
56	            String event) {
57	
58	        public OwnerCreatedEvent(long seq, Integer ownerId, String memberId, int membershipLevel) {
59	            this(seq, ownerId, memberId, membershipLevel, "OWNER_CREATED");
60	        }
61	    }
62	}
