21	        Set<String> existing = new HashSet<>();
22	        for (Owner other : ownerRepository.findAll()) {
23	            if (other.getId() != null && other.getId().equals(owner.getId())) {
24	                continue; // same record, not a collision
25	            }
26	            if (other.getMemberId() != null) {
27	                existing.add(other.getMemberId());
28	            }
29	        }
30	        owner.setMemberId(MemberId.dedupe(owner.getMemberId(), existing));
31	    }
